**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int x1, y1, x2, y2;
    plik >> x1 >> y1 >> x2 >> y2;
    int n;
    plik >> n;
    cout << "Prostokat: (" << x1 << "," << y1 << ")-(" << x2 << "," << y2 << ")" << endl;
    int cnt = 0;
    for (int i = 0; i < n; i++) {
        int x, y;
        plik >> x >> y;
        bool inside = (x >= x1 && x <= x2 && y >= y1 && y <= y2);
        cout << "(" << x << "," << y << "): " << (inside ? "WEWNATRZ" : "NA ZEWNATRZ") << endl;
        if (inside) cnt++;
    }
    cout << "Punkty wewnatrz: " << cnt << endl;
    return 0;
}
```

**Wyjasnienie**: Punkt jest w prostokacie, gdy obie jego wspolrzedne mieszcza sie w zakresie rogow prostokata (wlacznie z brzegiem).

Weryfikacja:
- (3,4): 1<=3<=7 i 2<=4<=6 -> WEWNATRZ
- (0,5): 0<1 -> NA ZEWNATRZ
- (7,6): 1<=7<=7 i 2<=6<=6 -> WEWNATRZ
- (8,3): 8>7 -> NA ZEWNATRZ
- (5,1): 1<2 -> NA ZEWNATRZ
- (1,2): 1<=1<=7 i 2<=2<=6 -> WEWNATRZ
- (4,7): 7>6 -> NA ZEWNATRZ
